{"command":"@'
import envparse
from envparse import parse_env

cases = [
    ("A=1\nB = 2 \n", {"A": "1", "B": "2"}),
    ("# c\n\n   \nA=1", {"A": "1"}),
    ('A="x\\ny"', {"A": "x\ny"}),
    ("A='x\\ny'", {"A": "x\\ny"}),
    ("A=hello  # trailing", {"A": "hello"}),
    ("A=a#b", {"A": "a#b"}),
    ("export FOO=bar", {"FOO": "bar"}),
    ("A=1\nA=2", {"A": "2"}),
    ("A=", {"A": ""}),
    ('A="  padded  "', {"A": "  padded  "}),
    ("URL=https://x/y?a=b", {"URL": "https://x/y?a=b"}),
]
for text, expected in cases:
    assert parse_env(text) == expected
for text, message in [("A=1\nnope\n", "invalid line 2: nope"), ("1BAD=x", "invalid line 1: 1BAD=x"), ("=x", "invalid line 1: =x")]:
    try:
        parse_env(text)
    except ValueError as error:
        assert str(error) == message
    else:
        raise AssertionError(text)
assert parse_env('A="\\n\\t\\r\\\"\\\\\\q"') == {"A": '\n\t\r"\\\\q'}
assert parse_env("A=one\t # comment") == {"A": "one"}
assert parse_env("A=one#two\nB=3\r\n") == {"A": "one#two", "B": "3"}
public = [name for name in vars(envparse) if not name.startswith("_")]
assert public == ["parse_env"], public
print("acceptance checks passed")
'@ | python -","description":"Rerun corrected parser acceptance checks"}

